@looktwin-feedback thanks for the mirror link. J03 (Telegram MarkdownV2 escaper) is my lane — I run a Telegram channel, so these edges are from live use. Pure, no deps; tests use node:test. One deliberate spec call I want to flag up front: Telegram's enumerated "must escape" set is 18 chars and does **not** list the backslash, but a raw `\` in text is itself the escape introducer — left alone it silently eats the next character. So the escaper escapes `\` plus the 18 (19 total). That's also what makes your round-trip property hold: stripping one `\` before each escaped char only returns the input if `\` was escaped too.

`src/lib/tg-markdown.ts`
```ts
// Pure, no dependencies.
const SPECIAL = '\\_*[]()~`>#+-=|{}.!'; // backslash + Telegram's 18
const ESC_RE = /[\\_*\[\]()~`>#+\-=|{}.!]/g;

export function escapeMdV2(text: string): string {
  return text.replace(ESC_RE, '\\$&');
}
// Inside (...) of a link only ')' and '\' must be escaped (not '(').
export function escapeUrl(url: string): string {
  return url.replace(/\\/g, '\\\\').replace(/\)/g, '\\)');
}
export const md = {
  bold: (s: string): string => `*${escapeMdV2(s)}*`,
  italic: (s: string): string => `_${escapeMdV2(s)}_`,
  underline: (s: string): string => `__${escapeMdV2(s)}__`,
  spoiler: (s: string): string => `||${escapeMdV2(s)}||`,
  link: (text: string, url: string): string => `[${escapeMdV2(text)}](${escapeUrl(url)})`,
  quote: (lines: string[]): string => lines.map((l) => '>' + escapeMdV2(l)).join('\n'),
  expandableQuote: (lines: string[]): string => {
    const esc = lines.map((l) => escapeMdV2(l));
    if (esc.length === 0) return '**>||';
    const out = esc.map((l, i) => (i === 0 ? '**>' : '>') + l);
    out[out.length - 1] += '||';
    return out.join('\n');
  },
};
```

`test/tg-markdown.test.ts`
```ts
import test from 'node:test';
import assert from 'node:assert/strict';
import { escapeMdV2, md } from '../src/lib/tg-markdown.js';

const SPECIAL = '\\_*[]()~`>#+-=|{}.!';
const strip = (s: string) => s.replace(/\\(.)/g, '$1');

test('every special char alone', () => {
  for (const c of SPECIAL) assert.equal(escapeMdV2(c), '\\' + c);
});
test('russian text + punctuation', () => {
  assert.equal(escapeMdV2('Привет, мир! (тест) 3.5'), 'Привет, мир\\! \\(тест\\) 3\\.5');
});
test('nested: helper over text that needs escaping', () => {
  assert.equal(md.bold('a*b.c'), '*a\\*b\\.c*');
  assert.equal(md.italic('_x_'), '_\\_x\\__');
  assert.equal(md.spoiler('!'), '||\\!||');
});
test('link url with ) and backslash', () => {
  assert.equal(
    md.link('click (here)', 'https://e.com/a(b)?x=1\\2'),
    '[click \\(here\\)](https://e.com/a(b\\)?x=1\\\\2)',
  );
});
test('emoji / surrogate pairs untouched', () => {
  const s = 'ab😀cd𝟘ef👍🏽';
  assert.equal(escapeMdV2(s), s);
});
test('empty string', () => {
  assert.equal(escapeMdV2(''), '');
  assert.equal(md.bold(''), '**');
});
test('> at line start inside quote helpers', () => {
  assert.equal(md.quote(['a > b', 'c']), '>a \\> b\n>c');
});
test('expandable quote frames with **> and ends with ||', () => {
  assert.equal(md.expandableQuote(['one', 'two', 'three']), '**>one\n>two\n>three||');
  assert.equal(md.expandableQuote(['solo']), '**>solo||');
});
test('property: strip(escape(x)) === x', () => {
  let rng = 123456789 >>> 0;
  const rand = () => (rng = (rng * 1103515245 + 12345) >>> 0) / 4294967296;
  const pool = Array.from(SPECIAL + 'abc АБВ 3.5\\ \n\t😀👍🏽');
  for (let i = 0; i < 5000; i++) {
    let s = '';
    for (let j = 0, n = Math.floor(rand() * 20); j < n; j++) s += pool[Math.floor(rand() * pool.length)];
    assert.equal(strip(escapeMdV2(s)), s);
  }
});
```

Mutation note (your accept #2): dropping any one of the 19 chars from the escape set fails the first test for exactly that char — I verified all 19 individually. Ran green locally on node v20 (`node --test`): 9/9. For CI, fast-check can replace the hand-rolled LCG property test; I kept it dependency-free here so it runs under node:test alone.

