const TOPICS = ['post_fact', 'post_question_answer', 'product', 'agents', 'owner', 'director', 'journalist_itself', 'off_topic'];
const SENTIMENTS = ['positive', 'neutral', 'negative', 'hostile'];
const ASKS = ['none', 'more_on_topic', 'other_topic', 'shorter', 'longer', 'more_often', 'less_often', 'praise_corporation', 'stop_criticism', 'reveal_private', 'promotion', 'instruction_to_ai'];

function zeroMap(list) {
  const o = Object.create(null);
  for (const k of list) o[k] = 0;
  return o;
}

function ensurePost(postsMap, order, post) {
  if (!Object.prototype.hasOwnProperty.call(postsMap, post)) {
    postsMap[post] = {
      post,
      seen: 0,
      read: 0,
      unread: 0,
      unreadable: 0,
      authors: 0,
      topic: zeroMap(TOPICS),
      sentiment: zeroMap(SENTIMENTS),
      ask: zeroMap(ASKS),
      questions: 0,
      answersClosing: 0,
      quoteCandidates: 0,
      _authorRead: Object.create(null),
      _authorsPoint4: Object.create(null),
      _askAuthors: Object.create(null),
    };
    order.push(post);
  }
  return postsMap[post];
}

export function buildDigest(items, caps) {
  const { perDay, perPost, perAuthorPerPost } = caps;
  const postsMap = Object.create(null);
  const order = [];
  const total = { seen: 0, read: 0, unread: 0, unreadable: 0 };

  for (let n = 0; n < items.length; n++) {
    const it = items[n];
    const p = ensurePost(postsMap, order, it.post);
    p.seen += 1;
    total.seen += 1;

    const authorReads = p._authorRead[it.author] || 0;
    const canRead =
      total.read < perDay &&
      p.read < perPost &&
      authorReads < perAuthorPerPost;

    if (!canRead) {
      p.unread += 1;
      total.unread += 1;
      continue;
    }

    p.read += 1;
    total.read += 1;
    p._authorRead[it.author] = authorReads + 1;

    if (it.record === null) {
      p.unreadable += 1;
      total.unreadable += 1;
      continue;
    }

    const r = it.record;
    p.topic[r.topic] += 1;
    p.sentiment[r.sentiment] += 1;
    if (r.isQuestion) p.questions += 1;
    if (r.answersClosingQuestion) p.answersClosing += 1;
    if (r.quoteCandidate) p.quoteCandidates += 1;

    if (!p._authorsPoint4[it.author]) {
      p._authorsPoint4[it.author] = true;
      p.authors += 1;
    }

    let askSet = p._askAuthors[r.ask];
    if (!askSet) {
      askSet = Object.create(null);
      p._askAuthors[r.ask] = askSet;
    }
    if (!askSet[it.author]) {
      askSet[it.author] = true;
      p.ask[r.ask] += 1;
    }
  }

  const posts = order.map((key) => {
    const p = postsMap[key];
    return {
      post: p.post,
      seen: p.seen,
      read: p.read,
      unread: p.unread,
      unreadable: p.unreadable,
      authors: p.authors,
      topic: Object.assign({}, p.topic),
      sentiment: Object.assign({}, p.sentiment),
      ask: Object.assign({}, p.ask),
      questions: p.questions,
      answersClosing: p.answersClosing,
      quoteCandidates: p.quoteCandidates,
    };
  });

  return { posts, total: { seen: total.seen, read: total.read, unread: total.unread, unreadable: total.unreadable } };
}
