const TOPICS = ["post_fact", "post_question_answer", "product", "agents", "owner", "director", "journalist_itself", "off_topic"] as const;
const SENTIMENTS = ["positive", "neutral", "negative", "hostile"] as const;
const ASKS = ["none", "more_on_topic", "other_topic", "shorter", "longer", "more_often", "less_often", "praise_corporation", "stop_criticism", "reveal_private", "promotion", "instruction_to_ai"] as const;
const NO_QUOTE: readonly string[] = ["praise_corporation", "stop_criticism", "reveal_private", "promotion", "instruction_to_ai"];
const KEYS = ["topic", "sentiment", "ask", "isQuestion", "answersClosingQuestion", "quoteCandidate"] as const;

export type Topic = (typeof TOPICS)[number];
export type Sentiment = (typeof SENTIMENTS)[number];
export type Ask = (typeof ASKS)[number];
export type ReaderRecord = {
  topic: Topic; sentiment: Sentiment; ask: Ask;
  isQuestion: boolean; answersClosingQuestion: boolean; quoteCandidate: boolean;
};
type Key = (typeof KEYS)[number];
type Result = { ok: true; record: ReaderRecord } | { ok: false; errors: string[] };

// Returns the list's own string, never the input value.
function member<T extends string>(list: readonly T[], v: unknown): T | undefined {
  if (typeof v !== "string") return undefined;
  for (const m of list) if (m === v) return m;
  return undefined;
}

export function validateReaderRecord(input: unknown): Result {
  try {
    if (typeof input !== "object" || input === null || Array.isArray(input)) return { ok: false, errors: ["not_object"] };
    const proto: unknown = Reflect.getPrototypeOf(input);
    if (proto !== Object.prototype && proto !== null) return { ok: false, errors: ["not_object"] };
    const errors: string[] = [];
    // One ownKeys call, one descriptor per known key. A data property is taken from
    // its descriptor, so no getter runs; an accessor is called exactly once.
    let extra = false;
    for (const k of Reflect.ownKeys(input)) if (typeof k !== "string" || member(KEYS, k) === undefined) extra = true;
    const copy = new Map<Key, unknown>();
    for (const k of KEYS) {
      const d = Reflect.getOwnPropertyDescriptor(input, k);
      if (d === undefined || d.enumerable !== true) { errors.push("missing:" + k); continue; }
      let v: unknown = undefined;
      if ("value" in d) v = d.value;
      else if (typeof d.get === "function") { try { v = Reflect.apply(d.get, input, []); } catch { v = undefined; } }
      copy.set(k, v);
    }
    if (extra) errors.push("extra_key");
    const topic = member(TOPICS, copy.get("topic"));
    const sentiment = member(SENTIMENTS, copy.get("sentiment"));
    const ask = member(ASKS, copy.get("ask"));
    if (copy.has("topic") && topic === undefined) errors.push("bad_topic");
    if (copy.has("sentiment") && sentiment === undefined) errors.push("bad_sentiment");
    if (copy.has("ask") && ask === undefined) errors.push("bad_ask");
    const flag = (k: Key): boolean | undefined => {
      const v = copy.get(k);
      if (typeof v === "boolean") return v;
      if (copy.has(k)) errors.push("bad_flag:" + k);
      return undefined;
    };
    const isQuestion = flag("isQuestion");
    const answersClosingQuestion = flag("answersClosingQuestion");
    const quoteCandidate = flag("quoteCandidate");
    if (ask !== undefined && NO_QUOTE.includes(ask) && quoteCandidate === true) errors.push("rule_5a");
    if (sentiment === "hostile" && quoteCandidate === true) errors.push("rule_5b");
    if (topic === "off_topic" && answersClosingQuestion === true) errors.push("rule_5c");
    if (errors.length > 0 || topic === undefined || sentiment === undefined || ask === undefined ||
        isQuestion === undefined || answersClosingQuestion === undefined || quoteCandidate === undefined) {
      return { ok: false, errors: errors.length > 0 ? errors : ["not_object"] };
    }
    return { ok: true, record: { topic, sentiment, ask, isQuestion, answersClosingQuestion, quoteCandidate } };
  } catch {
    return { ok: false, errors: ["not_object"] };
  }
}
```

