```python
from html.parser import HTMLParser

def _num(s):
    s = s.strip().upper()
    m = {"K": 1000, "M": 1000000}.get(s[-1:], 1)
    if m > 1:
        s = s[:-1]
    if s.count(".") > 1 or not s.replace(".", "") or not all(c in "0123456789." for c in s):
        return None
    return round(float(s) * m)

class _P(HTMLParser):
    subs = val = cur = cap = rx = own = None
    buf = ""
    date = in_b = False
    depth = 0

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        cls = (a.get("class") or "").split()
        if self.cur and tag == self.own:
            self.depth += 1
        if a.get("data-post"):
            t = a["data-post"].rsplit("/", 1)[-1]
            self.cur = self.cap = self.rx = None
            self.own, self.depth = tag, 1
            if t.isascii() and t.isdigit():
                self.cur = {"id": int(t), "published_utc": None, "views": None, "reactions": {}}
                self.posts.append(self.cur)
        elif tag == "span" and ("counter_value" in cls or "counter_type" in cls):
            self.cap, self.buf = cls, ""
        elif self.cur is None:
            pass
        elif tag == "span" and "tgme_widget_message_views" in cls:
            self.cap, self.buf = cls, ""
        elif tag == "span" and "tgme_reaction" in cls:
            self.rx = ["", ""]
        elif tag == "b":
            self.in_b = True
        elif tag == "a" and "tgme_widget_message_date" in cls:
            self.date = True
        elif tag == "time" and self.date and a.get("datetime") and not self.cur["published_utc"]:
            self.cur["published_utc"] = a["datetime"]

    def handle_data(self, data):
        if self.cap:
            self.buf += data
        elif self.rx:
            self.rx[0 if self.in_b else 1] += data

    def handle_endtag(self, tag):
        if self.cur and tag == self.own:
            self.depth -= 1
            if self.depth < 1:
                self.cur = self.rx = None
                if self.cap and "tgme_widget_message_views" in self.cap:
                    self.cap = None
        if tag == "b":
            self.in_b = False
        elif tag == "a":
            self.date = False
        elif tag == "span" and self.cap:
            cap, self.cap = self.cap, None
            if "counter_value" in cap:
                self.val = _num(self.buf)
            elif "counter_type" in cap:
                if self.buf.strip().lower() == "subscribers" and self.subs is None:
                    self.subs = self.val
                self.val = None
            elif self.cur:
                self.cur["views"] = _num(self.buf)
        elif tag == "span" and self.rx:
            e, n = self.rx[0].strip(), _num(self.rx[1])
            self.rx = None
            if self.cur and e and len(e) <= 16 and n is not None:
                self.cur["reactions"][e] = n

def parse_channel_page(html: str) -> dict:
    try:
        p = _P()
        p.posts = []
        p.feed(html)
        p.close()
        return {"subscribers": p.subs, "posts": p.posts}
    except Exception:
        return {"subscribers": None, "posts": []}
```

